// The server bundle is generated by `npm run build:pages` (vite.config.server.ts).
// Types come from functions/server-bundle.d.ts — the artifact itself carries none.
import { handleRequest } from '../.server/entry-server.mjs';
import type { AppEnv } from '../src/server/context';

export const onRequest = (context: { request: Request; env: Record<string, unknown> }) =>
  handleRequest(context.request, context.env as AppEnv, 'pages');
